362→        candidateEmail={r.candidate_email}
363→        jobTitle={jobTitle || "Open Position"}
364→        matchScore={Math.round(r.overall_score ?? 0)}
365→        resumeId={r.resume_id}
366→        jobId={r.id}
367→      />
368→    )}
369→    </>
370→  );
371→};
372→
373→export default CandidateRow;
